"""Independent reference implementations written straight from the spec.
Deliberately slow/naive; used only for differential testing."""
from math import gcd
from fractions import Fraction
import copy

PS = 10**6
NS = 10**9
INF = float('inf')

# ---------------- calibration ----------------

def ref_calibration(profile):
    """Return ('ok', D, H, C) or ('bad',) via Bellman-Ford per source."""
    K = profile['groups']
    edges = []
    for i, (a, b, L, U) in enumerate(profile['measurements']):
        edges.append((a, b, U, 2 * i))
        edges.append((b, a, -L, 2 * i + 1))
    # feasibility: BF from super source
    dist = [0] * K
    for it in range(K + 1):
        upd = False
        for a, b, w, i in edges:
            if dist[a] + w < dist[b]:
                dist[b] = dist[a] + w
                upd = True
        if not upd:
            break
    else:
        if upd:
            return ('bad',)
    D = [[0] * K for _ in range(K)]
    for s in range(K):
        d = [INF] * K
        d[s] = 0
        for _ in range(K - 1):
            for a, b, w, i in edges:
                if d[a] != INF and d[a] + w < d[b]:
                    d[b] = d[a] + w
        D[s] = d
    jit = profile['jitter_ps']
    H = [[0] * K for _ in range(K)]
    C = [[0] * K for _ in range(K)]
    for a in range(K):
        for b in range(K):
            hi = D[a][b]; lo = -D[b][a]
            H[a][b] = (hi - lo) * PS // 2 + (jit[a] + jit[b]) * PS
            C[a][b] = (hi + lo) * PS // 2
    return ('ok', D, H, C)

# ---------------- fabric calendar ----------------

def ref_fabric_setup(fabric):
    N = fabric['n']; T = fabric['interval_ns']; S = fabric['slice_ns']
    O = fabric['offset_ns']
    Q = len(fabric['slices'])
    mod = Q * S
    P = mod // gcd(T, mod)
    phase_slice = [((O + p * T) // S) % Q for p in range(P)]
    phase_rho = [(O + p * T) % S for p in range(P)]
    # effective rates (ppb) per device per phase
    V = [[fabric['drift_ppb'][i]] * P for i in range(N)]
    for (nd, st, en, ex) in fabric['heat']:
        for p in range(st, en):
            V[nd][p] += ex
    return P, N, T, S, phase_slice, phase_rho, V

def ref_dir_info(fabric, code):
    l = code // 2
    dr = code % 2
    lk = fabric['links'][l]
    e0 = lk['ends'][0]; e1 = lk['ends'][1]
    frm = e0 if dr == 0 else e1
    to = e1 if dr == 0 else e0
    d = lk['delay_ns'][dr]
    q = lk['defer_rounds'][dr]
    T = fabric['interval_ns']
    m = -(-d // T)
    return frm, to, d, q, m, m + q

def ref_blocked(fabric, l, p):
    """flight window blackout check at phase p for given dir info"""
    T = fabric['interval_ns']
    return None

def ref_hop_eligible(fabric, code, p, g, P):
    l = code // 2
    frm, to, d, q, m, L = ref_dir_info(fabric, code)
    S = fabric['slice_ns']
    if l not in fabric['slices'][ref_phase_slice_cached(p)]:
        return False
    # blackout: intervals [p, p+m-1]
    for (bl, st, en) in fabric['blackouts']:
        if bl != l:
            continue
        for x in range(p, p + m):
            if st <= (x % P) < en:
                return False
    rho = ref_phase_rho_cached(p)
    if rho < g or rho + d + g > S:
        return False
    return True

_C = {}
def ref_phase_slice_cached(p):
    return _C['fs'][p % _C['P']]
def ref_phase_rho_cached(p):
    return _C['fr'][p % _C['P']]

def ref_aging(VR, wnode, p, d, m, q, P, T):
    """receiver aging in as over [tr, pa) starting at phase p"""
    vh = VR[wnode]  # as per interval list
    part = m * T - d
    tot = part * vh[(p + d // T) % P]
    for j in range(p + m, p + m + q):
        tot += vh[j % P]
    return tot

def ref_plan(profile, fabric):
    cal = ref_calibration(profile)
    if cal[0] == 'bad':
        return {'status': 'inconsistent'}
    _, D, H, C = cal
    P, N, T, S, fsl, fro, Vppb = ref_fabric_setup(fabric)
    _C['P'] = P; _C['fs'] = fsl; _C['fr'] = fro
    VR = [[Vppb[i][p] * T for p in range(P)] for i in range(N)]
    anchors = fabric['anchors']
    guards = fabric['guards_ns']
    rc = fabric['reconfig_ns']

    def anchored(i, p):
        return any(a == i and a_st <= p < a_en for (a, a_st, a_en) in anchors)

    # per phase, list of (code, L, cost_err) eligible ignoring guard-size
    hops_at = {}
    for p in range(P):
        lst = []
        for l, lid in enumerate(fabric['slices'][fsl[p]]):
            for dr in (0, 1):
                code = 2 * lid + dr
                frm, to, d, q, m, L = ref_dir_info(fabric, code)
                # blackout
                bl = False
                for (b2, st, en) in fabric['blackouts']:
                    if b2 != lid:
                        continue
                    for x in range(p, p + m):
                        if st <= (x % P) < en:
                            bl = True
                            break
                    if bl:
                        break
                if bl:
                    continue
                gmax = min(fro[p], S - d - fro[p])
                gu = frm[2]; gw = to[2]
                cost = H[gu][gw] + ref_aging(VR, to[0], p, d, m, q, P, T)
                lst.append((code, frm[0], to[0], L, cost, gmax))
        hops_at[p] = lst

    def envelope_for(g):
        """time-expanded DP over absolute boundaries; returns B,A per cell."""
        # sufficient horizon: lineages simple -> <= 16*V steps
        VV = P * N
        Tmax = 16 * VV + 2 * P + 2
        NEG = None
        # E[i] = (err, age) lexicographic best lineage ending at boundary t
        Em = [dict() for _ in range(Tmax + 1)]
        prevE = None
        # store per boundary arrays
        Earr = [[None] * N for _ in range(Tmax + 1)]
        for t in range(Tmax + 1):
            p = t % P
            for i in range(N):
                if anchored(i, p):
                    Earr[t][i] = (0, 0)
