        A = [[None] * N for _ in range(P)]
        start = Tmax // 2  # min over all t is fine too, but later windows safer
        for p in range(P):
            for i in range(N):
                best = None
                for t in range(p, Tmax + 1, P):
                    v = Earr[t][i]
                    if v is not None and (best is None or v < best):
                        best = v
                if best is not None:
                    B[p][i] = best[0]
                    A[p][i] = best[1]
